// handler: 送られたキーごとに、検証した値だけを詰め替える
const input = body as Record<string, unknown>;
const changes: OrderDetailsChanges = {};
if ('shippingAddress' in input) changes.shippingAddress = parseShippingAddress(input.shippingAddress);
if ('deliveryNote' in input) changes.deliveryNote = parseDeliveryNote(input.deliveryNote);

// service: Object.assign をやめ、2 項目だけを写す
if ('shippingAddress' in changes) order.shippingAddress = changes.shippingAddress;
if ('deliveryNote' in changes) order.deliveryNote = changes.deliveryNote;

// checkout: 状態の確認の直後、PENDING_PAYMENT を保存する前に置く
if (order.status !== 'CART' && order.status !== 'PAYMENT_FAILED') {
  throw new InvalidOrderStateError(order);
}
if (!order.shippingAddress) throw new ShippingAddressRequiredError(order.id);

// テスト
await assert.rejects(service.checkout('o1'), ShippingAddressRequiredError);
assert.equal((await orders.get('o1'))?.status, 'CART');
assert.equal(payments.calls.length, 0);
